CREATE TABLE remodel_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, artifact_id TEXT NOT NULL);
CREATE TABLE remodel_calibration (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id));
CREATE TABLE remodel_parameters (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id));
CREATE TABLE remodel_results (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id));
CREATE TABLE remodel_asset (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id), ordinal INTEGER NOT NULL, asset_key TEXT NOT NULL, child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE remodel_durable_artifact (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id), ordinal INTEGER NOT NULL, content_id TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT, width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_durable_chunk (id INTEGER PRIMARY KEY, artifact_id INTEGER NOT NULL REFERENCES remodel_durable_artifact(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), field TEXT, field_tag INTEGER CHECK(field_tag BETWEEN 0 AND 255), element_type TEXT NOT NULL, element_count INTEGER NOT NULL CHECK(element_count>=0), octets BLOB, CHECK(COALESCE((element_type='raw' AND field IS NULL AND field_tag IS NULL AND octets IS NOT NULL AND element_count=length(octets)) OR (octets IS NULL AND ((field='samples' AND field_tag IS NULL AND element_type='f32') OR (field='absent' AND field_tag IS NULL AND element_type='u8' AND element_count=0) OR (field='unknown' AND field_tag BETWEEN 12 AND 255 AND element_type='u8') OR (field='positions' AND field_tag=0 AND element_type='f32') OR (field='normals' AND field_tag=1 AND element_type='f32') OR (field='colors' AND field_tag=2 AND element_type='f32') OR (field='indices' AND field_tag=3 AND element_type='u32') OR (field='uvs' AND field_tag=4 AND element_type='f32') OR (field='face_ids' AND field_tag=5 AND element_type='u32') OR (field='vertex_ids' AND field_tag=6 AND element_type='u32') OR (field='edge_positions' AND field_tag=7 AND element_type='f32') OR (field='edge_ids' AND field_tag=8 AND element_type='u32') OR (field='edge_uvs' AND field_tag=9 AND element_type='f32') OR (field='edge_is_seam' AND field_tag=10 AND element_type='u8') OR (field='paint_texture_base64' AND field_tag=11 AND element_type IN('text','invalid-text')))),0)));
CREATE TABLE remodel_durable_float (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), sample REAL, sample_bits INTEGER NOT NULL CHECK(sample_bits BETWEEN 0 AND 4294967295), sample_class TEXT NOT NULL CHECK(sample_class IN('finite','nan','positiveInfinity','negativeInfinity')), CHECK((sample_class!='finite' AND sample IS NULL) OR (sample_class='finite' AND sample IS NOT NULL)));
CREATE TABLE remodel_durable_integer (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_durable_byte (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), role TEXT NOT NULL CHECK(role IN('payload','trailing-word')), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE remodel_durable_text (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES remodel_durable_chunk(id), content TEXT NOT NULL);
CREATE TABLE remodel_stream (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id), ordinal INTEGER NOT NULL, stream_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('image-sequence','video')), camera_id TEXT, sync_offset_ms REAL, sync_offset_ms_bits INTEGER NOT NULL, sync_offset_ms_class TEXT NOT NULL, fps_hint REAL, fps_hint_bits INTEGER NOT NULL, fps_hint_class TEXT NOT NULL);
CREATE TABLE remodel_frame (id INTEGER PRIMARY KEY, stream_id INTEGER NOT NULL REFERENCES remodel_stream(id), ordinal INTEGER NOT NULL, frame_index INTEGER NOT NULL CHECK(frame_index BETWEEN 0 AND 4294967295), timestamp_ms REAL, timestamp_ms_bits INTEGER NOT NULL, timestamp_ms_class TEXT NOT NULL, asset_id TEXT NOT NULL);
CREATE TABLE remodel_video_source (id INTEGER PRIMARY KEY, stream_id INTEGER NOT NULL REFERENCES remodel_stream(id), name TEXT NOT NULL, container TEXT NOT NULL, codec TEXT NOT NULL CHECK(codec IN('avc','hevc','vp9','av1','mjpeg','unknown')), duration_ms REAL, duration_ms_bits INTEGER NOT NULL, duration_ms_class TEXT NOT NULL, frame_count INTEGER NOT NULL CHECK(frame_count BETWEEN 0 AND 4294967295), width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_camera (id INTEGER PRIMARY KEY, calibration_id INTEGER NOT NULL REFERENCES remodel_calibration(id), ordinal INTEGER NOT NULL, camera_id TEXT NOT NULL, label TEXT NOT NULL, model TEXT NOT NULL, fx REAL, fx_bits INTEGER NOT NULL, fx_class TEXT NOT NULL, fy REAL, fy_bits INTEGER NOT NULL, fy_class TEXT NOT NULL, cx REAL, cx_bits INTEGER NOT NULL, cx_class TEXT NOT NULL, cy REAL, cy_bits INTEGER NOT NULL, cy_class TEXT NOT NULL, skew REAL, skew_bits INTEGER NOT NULL, skew_class TEXT NOT NULL, rms_reprojection_px REAL, rms_reprojection_px_bits INTEGER, rms_reprojection_px_class TEXT, locked INTEGER NOT NULL CHECK(locked IN(0,1)));
CREATE TABLE remodel_camera_distortion (id INTEGER PRIMARY KEY, camera_id INTEGER NOT NULL REFERENCES remodel_camera(id), ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 4), coefficient REAL, coefficient_bits INTEGER NOT NULL CHECK(coefficient_bits BETWEEN 0 AND 4294967295), coefficient_class TEXT NOT NULL);
CREATE TABLE remodel_rig_extrinsic (id INTEGER PRIMARY KEY, calibration_id INTEGER NOT NULL REFERENCES remodel_calibration(id), ordinal INTEGER NOT NULL, camera_id TEXT NOT NULL, rotation_w REAL, rotation_w_bits INTEGER NOT NULL, rotation_w_class TEXT NOT NULL, rotation_x REAL, rotation_x_bits INTEGER NOT NULL, rotation_x_class TEXT NOT NULL, rotation_y REAL, rotation_y_bits INTEGER NOT NULL, rotation_y_class TEXT NOT NULL, rotation_z REAL, rotation_z_bits INTEGER NOT NULL, rotation_z_class TEXT NOT NULL, translation_x_m REAL, translation_x_m_bits INTEGER NOT NULL, translation_x_m_class TEXT NOT NULL, translation_y_m REAL, translation_y_m_bits INTEGER NOT NULL, translation_y_m_class TEXT NOT NULL, translation_z_m REAL, translation_z_m_bits INTEGER NOT NULL, translation_z_m_class TEXT NOT NULL);
CREATE TABLE remodel_ground_control_point (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES remodel_document(id), ordinal INTEGER NOT NULL, point_id TEXT NOT NULL, name TEXT NOT NULL, world_x REAL, world_x_bits INTEGER NOT NULL, world_x_class TEXT NOT NULL, world_y REAL, world_y_bits INTEGER NOT NULL, world_y_class TEXT NOT NULL, world_z REAL, world_z_bits INTEGER NOT NULL, world_z_class TEXT NOT NULL);
CREATE TABLE remodel_ground_control_observation (id INTEGER PRIMARY KEY, point_id INTEGER NOT NULL REFERENCES remodel_ground_control_point(id), ordinal INTEGER NOT NULL, stream_id TEXT NOT NULL, frame_index INTEGER NOT NULL CHECK(frame_index BETWEEN 0 AND 4294967295), pixel_x REAL, pixel_x_bits INTEGER NOT NULL, pixel_x_class TEXT NOT NULL, pixel_y REAL, pixel_y_bits INTEGER NOT NULL, pixel_y_class TEXT NOT NULL);
CREATE TABLE remodel_ingest_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), frame_sample_stride INTEGER NOT NULL CHECK(frame_sample_stride BETWEEN 0 AND 4294967295), max_frames INTEGER NOT NULL CHECK(max_frames BETWEEN 0 AND 4294967295), downscale_long_edge_px INTEGER NOT NULL CHECK(downscale_long_edge_px BETWEEN 0 AND 4294967295), min_sharpness REAL, min_sharpness_bits INTEGER NOT NULL, min_sharpness_class TEXT NOT NULL);
CREATE TABLE remodel_feature_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), detector TEXT NOT NULL CHECK(detector IN('orb','akaze','harris')), target_count INTEGER NOT NULL CHECK(target_count BETWEEN 0 AND 4294967295), octaves INTEGER NOT NULL CHECK(octaves BETWEEN 0 AND 4294967295), edge_threshold REAL, edge_threshold_bits INTEGER NOT NULL, edge_threshold_class TEXT NOT NULL);
CREATE TABLE remodel_match_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), matcher TEXT NOT NULL CHECK(matcher IN('brute-force','kd-tree')), ratio_test REAL, ratio_test_bits INTEGER NOT NULL, ratio_test_class TEXT NOT NULL, cross_check INTEGER NOT NULL CHECK(cross_check IN(0,1)), sequential_window INTEGER NOT NULL CHECK(sequential_window BETWEEN 0 AND 4294967295), max_pairs_per_frame INTEGER NOT NULL CHECK(max_pairs_per_frame BETWEEN 0 AND 4294967295), loop_closure INTEGER NOT NULL CHECK(loop_closure IN(0,1)));
CREATE TABLE remodel_sfm_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), ransac_iterations INTEGER NOT NULL CHECK(ransac_iterations BETWEEN 0 AND 4294967295), ransac_threshold_px REAL, ransac_threshold_px_bits INTEGER NOT NULL, ransac_threshold_px_class TEXT NOT NULL, min_track_length INTEGER NOT NULL CHECK(min_track_length BETWEEN 0 AND 4294967295), ba_max_iterations INTEGER NOT NULL CHECK(ba_max_iterations BETWEEN 0 AND 4294967295), robust_loss TEXT NOT NULL CHECK(robust_loss IN('l2','huber','cauchy')), huber_delta_px REAL, huber_delta_px_bits INTEGER NOT NULL, huber_delta_px_class TEXT NOT NULL);
CREATE TABLE remodel_dense_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), resolution TEXT NOT NULL CHECK(resolution IN('low','medium','high')), window_radius_px INTEGER NOT NULL CHECK(window_radius_px BETWEEN 0 AND 4294967295), min_view_consistency INTEGER NOT NULL CHECK(min_view_consistency BETWEEN 0 AND 4294967295), confidence_threshold REAL, confidence_threshold_bits INTEGER NOT NULL, confidence_threshold_class TEXT NOT NULL, max_points INTEGER NOT NULL CHECK(max_points BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_mesh_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), tsdf_voxel_size_mm REAL, tsdf_voxel_size_mm_bits INTEGER NOT NULL, tsdf_voxel_size_mm_class TEXT NOT NULL, tsdf_truncation_mm REAL, tsdf_truncation_mm_bits INTEGER NOT NULL, tsdf_truncation_mm_class TEXT NOT NULL, decimate_target_triangles INTEGER NOT NULL CHECK(decimate_target_triangles BETWEEN 0 AND 4294967295), smoothing_iterations INTEGER NOT NULL CHECK(smoothing_iterations BETWEEN 0 AND 4294967295), texture_enabled INTEGER NOT NULL CHECK(texture_enabled IN(0,1)), texture_size INTEGER NOT NULL CHECK(texture_size BETWEEN 0 AND 4294967295), guarantee_watertight INTEGER NOT NULL CHECK(guarantee_watertight IN(0,1)), hole_fill_max_boundary_verts INTEGER NOT NULL CHECK(hole_fill_max_boundary_verts BETWEEN 0 AND 4294967295), self_intersection_check INTEGER NOT NULL CHECK(self_intersection_check IN(0,1)));
CREATE TABLE remodel_motion_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), max_tracks INTEGER NOT NULL CHECK(max_tracks BETWEEN 0 AND 4294967295), track_window_px INTEGER NOT NULL CHECK(track_window_px BETWEEN 0 AND 4294967295), min_track_quality REAL, min_track_quality_bits INTEGER NOT NULL, min_track_quality_class TEXT NOT NULL, min_track_length_frames INTEGER NOT NULL CHECK(min_track_length_frames BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_geo_parameters (id INTEGER PRIMARY KEY, parameters_id INTEGER NOT NULL REFERENCES remodel_parameters(id), enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), origin_lon REAL, origin_lon_bits INTEGER, origin_lon_class TEXT, origin_lat REAL, origin_lat_bits INTEGER, origin_lat_class TEXT, origin_alt REAL, origin_alt_bits INTEGER, origin_alt_class TEXT, gsd_m REAL, gsd_m_bits INTEGER NOT NULL, gsd_m_class TEXT NOT NULL, dsm_cell_m REAL, dsm_cell_m_bits INTEGER NOT NULL, dsm_cell_m_class TEXT NOT NULL, dtm_filter_radius_m REAL, dtm_filter_radius_m_bits INTEGER NOT NULL, dtm_filter_radius_m_class TEXT NOT NULL, ortho_max_px INTEGER NOT NULL CHECK(ortho_max_px BETWEEN 0 AND 4294967295));
CREATE TABLE remodel_mesh_result (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('placeholder','reconstructed','imported')), texture_asset_id TEXT);
CREATE TABLE remodel_cloud (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id), slot TEXT NOT NULL CHECK(slot IN('sparse','dense')));
CREATE TABLE remodel_float_buffer (id INTEGER PRIMARY KEY, cloud_id INTEGER NOT NULL REFERENCES remodel_cloud(id), slot TEXT NOT NULL CHECK(slot IN('points','positions','confidence')), storage TEXT NOT NULL CHECK(storage IN('inline','content')), content_id TEXT, chunk_count TEXT, chunk_count_bits INTEGER);
CREATE TABLE remodel_float_sample (id INTEGER PRIMARY KEY, buffer_id INTEGER NOT NULL REFERENCES remodel_float_buffer(id), ordinal INTEGER NOT NULL, sample REAL, sample_bits INTEGER NOT NULL CHECK(sample_bits BETWEEN 0 AND 4294967295), sample_class TEXT NOT NULL CHECK(sample_class IN('finite','nan','positiveInfinity','negativeInfinity')));
CREATE TABLE remodel_byte_buffer (id INTEGER PRIMARY KEY, cloud_id INTEGER NOT NULL REFERENCES remodel_cloud(id), slot TEXT NOT NULL CHECK(slot IN('colors','classification')), octets BLOB NOT NULL);
CREATE TABLE remodel_trajectory (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id));
CREATE TABLE remodel_camera_pose (id INTEGER PRIMARY KEY, trajectory_id INTEGER NOT NULL REFERENCES remodel_trajectory(id), ordinal INTEGER NOT NULL, camera_id TEXT NOT NULL, rotation_w REAL, rotation_w_bits INTEGER NOT NULL, rotation_w_class TEXT NOT NULL, rotation_x REAL, rotation_x_bits INTEGER NOT NULL, rotation_x_class TEXT NOT NULL, rotation_y REAL, rotation_y_bits INTEGER NOT NULL, rotation_y_class TEXT NOT NULL, rotation_z REAL, rotation_z_bits INTEGER NOT NULL, rotation_z_class TEXT NOT NULL, translation_x REAL, translation_x_bits INTEGER NOT NULL, translation_x_class TEXT NOT NULL, translation_y REAL, translation_y_bits INTEGER NOT NULL, translation_y_class TEXT NOT NULL, translation_z REAL, translation_z_bits INTEGER NOT NULL, translation_z_class TEXT NOT NULL);
CREATE TABLE remodel_motion_track (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id), ordinal INTEGER NOT NULL, track_id TEXT NOT NULL, length INTEGER NOT NULL CHECK(length BETWEEN 0 AND 4294967295), class TEXT NOT NULL CHECK(class IN('static','moving')), mean_speed_m_s REAL, mean_speed_m_s_bits INTEGER NOT NULL, mean_speed_m_s_class TEXT NOT NULL);
CREATE TABLE remodel_geo_products (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id), dsm_asset_id TEXT, dtm_asset_id TEXT, ortho_asset_id TEXT);
CREATE TABLE remodel_qc_report (id INTEGER PRIMARY KEY, results_id INTEGER NOT NULL REFERENCES remodel_results(id), reprojection_rms_px REAL, reprojection_rms_px_bits INTEGER NOT NULL, reprojection_rms_px_class TEXT NOT NULL, gcp_checkpoint_rmse REAL, gcp_checkpoint_rmse_bits INTEGER, gcp_checkpoint_rmse_class TEXT, mean_track_length REAL, mean_track_length_bits INTEGER NOT NULL, mean_track_length_class TEXT NOT NULL, registered_frame_ratio REAL, registered_frame_ratio_bits INTEGER NOT NULL, registered_frame_ratio_class TEXT NOT NULL, dense_coverage_ratio REAL, dense_coverage_ratio_bits INTEGER NOT NULL, dense_coverage_ratio_class TEXT NOT NULL);
CREATE TABLE remodel_qc_warning (id INTEGER PRIMARY KEY, qc_id INTEGER NOT NULL REFERENCES remodel_qc_report(id), ordinal INTEGER NOT NULL, warning TEXT NOT NULL);
CREATE TABLE remodel_watertight_report (id INTEGER PRIMARY KEY, mesh_id INTEGER REFERENCES remodel_mesh_result(id), qc_id INTEGER REFERENCES remodel_qc_report(id), vertex_count INTEGER NOT NULL CHECK(vertex_count BETWEEN 0 AND 4294967295), triangle_count INTEGER NOT NULL CHECK(triangle_count BETWEEN 0 AND 4294967295), boundary_edge_count INTEGER NOT NULL CHECK(boundary_edge_count BETWEEN 0 AND 4294967295), boundary_loop_count INTEGER NOT NULL CHECK(boundary_loop_count BETWEEN 0 AND 4294967295), non_manifold_edge_count INTEGER NOT NULL CHECK(non_manifold_edge_count BETWEEN 0 AND 4294967295), non_manifold_vertex_count INTEGER NOT NULL CHECK(non_manifold_vertex_count BETWEEN 0 AND 4294967295), connected_components INTEGER NOT NULL CHECK(connected_components BETWEEN 0 AND 4294967295), consistently_oriented INTEGER NOT NULL CHECK(consistently_oriented IN(0,1)), euler_characteristic INTEGER NOT NULL, genus INTEGER, signed_volume REAL, signed_volume_bits INTEGER NOT NULL, signed_volume_class TEXT NOT NULL, self_intersection_pairs INTEGER CHECK(self_intersection_pairs BETWEEN 0 AND 4294967295), closed_fallback_used INTEGER NOT NULL CHECK(closed_fallback_used IN(0,1)), is_closed INTEGER NOT NULL CHECK(is_closed IN(0,1)), is_two_manifold INTEGER NOT NULL CHECK(is_two_manifold IN(0,1)), is_watertight INTEGER NOT NULL CHECK(is_watertight IN(0,1)), CHECK((mesh_id IS NULL) != (qc_id IS NULL)));
